import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.B9qR_F1m.js";const a="/bilder/iads.jpg",g=JSON.parse('{"title":"IADS","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/iads.md","filePath":"bereiche/iads.md"}'),s={name:"bereiche/iads.md"};function d(o,e,l,h,m,u){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="iads" tabindex="-1">IADS <a class="header-anchor" href="#iads" aria-label="Permalink to &quot;IADS&quot;">​</a></h1><p>Ein <strong>Integrated Air Defense System</strong> ist mehr als eine Ansammlung von SAMs: Frühwarnradare melden Ziele, Gefechtsstände verteilen das Lagebild, Kraftwerke liefern Strom. Fällt ein Knoten aus, kämpfen die Stellungen allein weiter. Mit dem IADS-Werkzeug baust du dieses Netz – und Shardwing schreibt alles, was ein Lua-IADS-Skript in DCS dafür braucht, in die Mission.</p><p>Nur der Mission Designer sieht diesen Bereich. Piloten sehen vom IADS nur, was du als <a href="./intel">Intel</a> freigibst.</p><p><img src="'+a+'" alt="IADS-Werkzeug mit Stellungsliste, Karte und Netz-Editor" loading="lazy"></p><h2 id="die-idee-im-iads-ist-wer-so-heißt" tabindex="-1">Die Idee: Im IADS ist, wer so heißt <a class="header-anchor" href="#die-idee-im-iads-ist-wer-so-heißt" aria-label="Permalink to &quot;Die Idee: Im IADS ist, wer so heißt&quot;">​</a></h2><p>Im Mission Editor stellst du SAMs einfach hin, Namen egal. Shardwing gibt ihnen in einem Rutsch <strong>Namen nach Konvention</strong> – und damit sind sie im IADS:</p><table tabindex="0"><thead><tr><th>Rolle</th><th>Name</th><th>Beispiel</th></tr></thead><tbody><tr><td>SAM-Stellung</td><td><code>Red SAM &lt;Typ&gt; &lt;Ort&gt; #&lt;Nr&gt;</code></td><td><code>Red SAM SA-10 Damaskus Nord #1</code></td></tr><tr><td>Nahbereichsschutz</td><td><code>Red SHORAD &lt;Ort&gt; #&lt;Nr&gt;</code></td><td><code>Red SHORAD Palmyra #2</code></td></tr><tr><td>Frühwarnradar</td><td><code>Red EWR &lt;Ort&gt; #&lt;Nr&gt;</code></td><td><code>Red EWR Golan #2</code></td></tr><tr><td>AWACS</td><td><code>Red AWACS #&lt;Nr&gt;</code></td><td><code>Red AWACS #1</code></td></tr></tbody></table><p>Der Ort kommt vom nächsten Flugplatz, die Nummer zählt fortlaufend. Passende Nummern bleiben.</p><h2 id="schritt-fur-schritt" tabindex="-1">Schritt für Schritt <a class="header-anchor" href="#schritt-fur-schritt" aria-label="Permalink to &quot;Schritt für Schritt&quot;">​</a></h2><ol class="steps"><li><b>Stellungen wählen.</b> Links die Liste aller Luftabwehr-Gruppen (SAM, SHORAD, AAA, MANPADS, EWR, AWACS). Klick wählt, <kbd>Shift</kbd>-Klick wählt mehrere.</li><li><b>Nach Konvention benennen.</b> Damit sind sie im IADS. Auf Wunsch werden auch die Einheiten der Gruppe durchnummeriert.</li><li><b>Knoten setzen.</b> Mit <b>+ CP / CN / PP</b> Command Post, Connection Node und Power Plant auf die Karte setzen. Ohne Knoten ist alles <i>integriert</i> – ein gemeinsames Lagebild.</li><li><b>Verbinden.</b> Im Netz vom Ring um ein Symbol zu einem anderen ziehen. Was nicht geht, wird nicht angeboten.</li><li><b>Einbauen.</b> <b>Beim Speichern einbauen</b> anschalten und die Mission speichern.</li></ol><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>Über der Liste filterst du nach Koalition (Rot/Blau/Alle), Art, Typ (SA-2, SA-10 …), <em>im IADS / noch nicht</em>, <strong>mit Hinweis</strong> und <strong>nur Kartenausschnitt</strong>. Auswahl in der Liste hebt die Stellung auf der Karte hervor und umgekehrt.</p><h2 id="hinweise" tabindex="-1">Hinweise <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Hinweise&quot;">​</a></h2><p>Shardwing prüft jeden Namen und sagt, was nicht passt – zum Beispiel:</p><ul><li><em>heißt AAA, ist aber SAM</em> – Rolle im Namen passt nicht zu den Einheiten</li><li><em>Typ „SA-3“ im Namen, erkannt SA-2</em></li><li><em>SAM-1 doppelt</em> – Nummer zweimal vergeben</li><li><em>vom Mission Editor kopiert (-Nr am Ende)</em> – der ME hängt beim Kopieren „-1“ an</li><li><em>Late Activation: im IADS nicht erlaubt</em></li><li><em>passt nicht zur Konvention</em></li></ul><p>Was so in der Mission nicht geht, ist rot markiert – der Export würde verweigert. Ein Klick auf die Fehlerzahl oben zeigt nur diese Stellungen.</p><h2 id="der-netz-editor" tabindex="-1">Der Netz-Editor <a class="header-anchor" href="#der-netz-editor" aria-label="Permalink to &quot;Der Netz-Editor&quot;">​</a></h2><p>Rechts neben der Karte die Knoten als Symbole, Verbindungen als Linien:</p><table tabindex="0"><thead><tr><th>Linie</th><th>Bedeutung</th></tr></thead><tbody><tr><td>─── <strong>Daten</strong></td><td>SAM, SHORAD, EWR zu einem Connection Node oder Command Post</td></tr><tr><td>- - - <strong>Strom</strong></td><td>vom Power Plant zum Knoten</td></tr><tr><td>····· <strong>Schutz</strong></td><td>eine SHORAD schützt eine SAM</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Farbe</th><th>Zustand</th></tr></thead><tbody><tr><td><span class="dot green"></span> grün</td><td><strong>integriert</strong> – hängt an einem Sektor mit Command Post</td></tr><tr><td><span class="dot yellow"></span> gelb</td><td><strong>autonom</strong> – ohne Verbindung, sendet dauerhaft</td></tr><tr><td><span class="dot purple"></span> lila</td><td><strong>kein Strom</strong></td></tr><tr><td><span class="dot red"></span> rot</td><td><strong>zerstört</strong> (Was-wäre-wenn)</td></tr></tbody></table><p>Bedienung: Symbol ziehen verschiebt, <kbd>Shift</kbd>+Ziehen oder <strong>Auswählen</strong> zieht einen Rahmen um mehrere, <kbd>Entf</kbd> nimmt Ausgewähltes aus dem IADS. <strong>Einpassen</strong> holt alles ins Bild. Ohne eigene Positionen liegen die Symbole wie auf der Karte (Norden oben); <strong>Nach Ebenen</strong> ordnet sie stattdessen in Reihen (Command Posts oben, darunter Connection Nodes mit ihren Stellungen, Power Plants unten), <strong>Wie auf der Karte</strong> holt die Kartenlage zurück.</p><h3 id="was-ware-wenn" tabindex="-1">Was-wäre-wenn <a class="header-anchor" href="#was-ware-wenn" aria-label="Permalink to &quot;Was-wäre-wenn&quot;">​</a></h3><p>Schalt <strong>Was-wäre-wenn</strong> an und klick Knoten aus: Shardwing zeigt, was wegfällt. Kraftwerk aus → Stellungen ohne Strom. Command Post weg → der Sektor kämpft autonom. Daraus ergibt sich, welche Ziele für SEAD/DEAD am meisten bringen. Wird nicht gespeichert.</p><h2 id="was-in-die-mission-kommt" tabindex="-1">Was in die Mission kommt <a class="header-anchor" href="#was-in-die-mission-kommt" aria-label="Permalink to &quot;Was in die Mission kommt&quot;">​</a></h2><p>Mit <strong>Beim Speichern einbauen</strong> schreibt Shardwing beim Speichern:</p><ul><li>die <strong>neuen Namen</strong> der Gruppen (nur die Namensfelder),</li><li><strong>Command Post, Connection Node und Power Plant</strong> als Static-Objekte (Command Center, Funkturm, Generator),</li><li>die Skripte <strong>MOOSE</strong>, <strong>EMCON</strong>, <strong>IADS</strong> und eine Netz-Datei mit deiner Konfiguration,</li><li>einen <strong>MISSION-START-Trigger</strong>, der sie lädt. Vorhandene Trigger bleiben unangetastet.</li></ul><p><strong>Debug</strong> schreibt IADS- und EMCON-Zeilen ins <code>dcs.log</code> und meldet HARM-Starts und SAM an/aus im Spiel – zum Testen; für fertige Missionen ausschalten.</p><div class="warning custom-block"><p class="custom-block-title">Andere IADS-Skripte</p><p>Lädt die Mission schon selbst MOOSE oder ein anderes IADS-Skript (z. B. Skynet), warnt Shardwing – sonst liefe MOOSE doppelt. Mit <strong>Alte Lade-Trigger entfernen</strong> räumst du sie auf.</p></div><div class="info custom-block"><p class="custom-block-title">Gemeinsames Planen</p><p>Beim Planen über den Server baut der Server die Skripte noch nicht ein. Für das IADS die Mission lokal speichern.</p></div><p>Steht ein Gruppenname schon in einem Trigger oder Skript der Mission, zeigt Shardwing das an (<em>in Skript/Trigger</em>), bevor du umbenennst.</p>',30)])])}const b=t(s,[["render",d]]);export{g as __pageData,b as default};
